def check_tournament(m, n, top_points):
    # Check if the sum of points for the top n players is consistent
    total_points = [0] * m
    for i in range(m):
        for j in range(m):
            if i != j:
                total_points[i] += 1  # Assume a draw for simplicity

    # Check if the sum of points for the top n players matches the given top_points
    if sorted(total_points, reverse=True)[:n] != top_points:
        return 'no', None

    # Construct the tournament table
    tournament_table = [['D' if i != j else 'X' for j in range(m)] for i in range(m)]

    # Adjust the table to match the given top_points
    for i in range(m):
        for j in range(m):
            if i != j:
                if total_points[i] < top_points[0]:
                    tournament_table[i][j] = 'L'
                    tournament_table[j][i] = 'W'
                    total_points[i] += 1
                    total_points[j] += 1
                elif total_points[i] > top_points[0]:
                    tournament_table[i][j] = 'W'
                    tournament_table[j][i] = 'L'
                    total_points[i] += 1
                    total_points[j] += 1

    return 'yes', tournament_table

